<?= $this->extend('layout') ?><?= $this->section('content') ?><section class="card"><h1>Record Sale</h1><form method="post" action="<?= site_url('sales') ?>"><?= csrf_field() ?><label for="product_id">Product</label><select id="product_id" name="product_id" required><option value="">Choose a product</option><?php foreach($products as $product): ?><option value="<?= esc($product['id']) ?>" <?= old('product_id')==$product['id']?'selected':'' ?>><?= esc($product['name']) ?> — <?= esc($product['stock_quantity']) ?> in stock — ₱<?= esc($product['price']) ?></option><?php endforeach ?></select><label for="customer_id">Customer (optional)</label><select id="customer_id" name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $customer): ?><option value="<?= esc($customer['id']) ?>"><?= esc($customer['full_name']) ?></option><?php endforeach ?></select><label for="quantity">Quantity</label><input id="quantity" type="number" name="quantity" min="1" required value="<?= esc(old('quantity','1')) ?>"><p><button>Record Sale</button></p></form></section><?= $this->endSection() ?>
